**2. 计算器状态管理（`store/calculator.ts`）**

```typescript
import { defineStore } from ''pinia''
import { ref, computed } from ''vue''
import { CalculatorEngine } from ''@/components/calculator/CalculatorEngine''
import type { CalculatorState, Operator } from ''@/types/calculator''

export const useCalculatorStore = defineStore(''calculator'', () => {
  // 状态
  const display = ref<string>(''0'')
  const operand1 = ref<string | null>(null)
  const operator = ref<Operator | null>(null)
  const operand2 = ref<string | null>(null)
  const isError = ref<boolean>(false)
  const errorMessage = ref<string | null>(null)
  const isInputting = ref<boolean>(false)

  // 计算引擎实例
  const engine = new CalculatorEngine()

  // 输入数字
  const inputNumber = (num: string) => {
    if (isError.value) {
      clear(''AC'')
    }
    
    if (!isInputting.value) {
      display.value = num === ''.'' ? ''0.'' : num
      isInputting.value = true
    } else {
      if (num === ''.'' && display.value.includes(''.'')) {
        return // 忽略重复小数点
      }
      display.value += num
    }
  }

  // 设置运算符
  const setOperator = (op: Operator) => {
    if (isError.value) return

    if (operand1.value === null) {
      operand1.value = display.value
      operator.value = op
      isInputting.value = false
    } else if (isInputting.value) {
      // 已有操作数1和运算符，执行上一次计算
      operand2.value = display.value
      const result = engine.calculate(operand1.value, operator.value!, operand2.value)
      if (result.error) {
        handleError(result.error)
        return
      }
      display.value = result.value!
      operand1.value = result.value!
      operator.value = op
      operand2.value = null
      isInputting.value = false
    } else {
      // 更新运算符
      operator.value = op
    }
  }

  // 执行计算
  const calculate = () => {
    if (isError.value || operator.value === null) return

    if (operand1.value === null) {
      operand1.value = display.value
      return
    }

    operand2.value = isInputting.value ? display.value : operand1.value
    const result = engine.calculate(operand1.value, operator.value, operand2.value)
    
    if (result.error) {
      handleError(result.error)
      return
    }

    display.value = result.value!
    operand1.value = result.value!
    operator.value = null
    operand2.value = null
    isInputting.value = false
  }

  // 清除
  const clear = (type: ''C'' | ''AC'') => {
    if (type === ''AC'') {
      operand1.value = null
      operator.value = null
      operand2.value = null
    }
    display.value = ''0''
    isError.value = false
    errorMessage.value = null
    isInputting.value = false
  }

  // 错误处理
  const handleError = (error: string) => {
    isError.value = true
    errorMessage.value = error
    display.value = error
  }

  return {
    display,
    isError,
    errorMessage,
    inputNumber,
    setOperator,
    calculate,
    clear
  }
})
```

**3. 计算引擎（`components/calculator/CalculatorEngine.ts`）**

```typescript
import Decimal from ''decimal.js''
import type { Operator } from ''@/types/calculator''

export interface CalculationResult {
  value: string | null
  error: string | null
}

export class CalculatorEngine {
  /**
   * 执行计算
   */
  calculate(operand1: string, operator: Operator, operand2: string): CalculationResult {
    try {
      // 验证输入
      const num1 = this.parseNumber(operand1)
      const num2 = this.parseNumber(operand2)
      
      if (num1 === null || num2 === null) {
        return { value: null, error: ''输入格式错误'' }
      }

      // 除零检查
      if (operator === ''÷'' && num2.isZero()) {
        return { value: null, error: ''除数不能为零'' }
      }

      // 执行计算
      let result: Decimal
      switch (operator) {
        case ''+'':
          result = num1.plus(num2)
          break
        case ''-'':
          result = num1.minus(num2)
          break
        case ''×'':
          result = num1.times(num2)
          break
        case ''÷'':
          result = num1.dividedBy(num2)
          break
        default:
          return { value: null, error: ''未知运算符'' }
      }

      // 溢出检查
      if (this.isOverflow(result)) {
        return { value: null, error: ''结果超出范围'' }
      }

      // 格式化结果
      const formatted = this.formatResult(result)
      return { value: formatted, error: null }
    } catch (error) {
      return { value: null, error: ''计算错误'' }
    }
  }

  /**
   * 解析数字字符串为 Decimal
   */
  private parseNumber(str: string): Decimal | null {
    try {
      return new Decimal(str)
    } catch {
      return null
    }
  }

  /**
   * 检查是否溢出
   */
  private isOverflow(num: Decimal): boolean {
    const maxSafeInteger = new Decimal(2).pow(53).minus(1)
    const minSafeInteger = maxSafeInteger.negated()
    return num.greaterThan(maxSafeInteger) || num.lessThan(minSafeInteger)
  }

  /**
   * 格式化结果
   */
  private formatResult(num: Decimal): string {
    // 最多显示10位小数，去除末尾零
    const str = num.toFixed(10)
    return str.replace(/\.?0+$/, '''')
  }
}
```

