      <CalculatorDisplay :display="store.display" :is-error="store.isError" />
      <CalculatorError v-if="store.isError" :message="store.errorMessage" />
      <div class="button-grid">
        <!-- 按钮布局与移动端类似，使用 Element Plus 按钮样式 -->
        <ElButton 
          v-for="btn in buttonConfigs" 
          :key="btn.value"
          :type="btn.type"
          :class="btn.className"
          @click="handleButtonClick(btn)"
        >
          {{ btn.label }}
        </ElButton>
      </div>
    </ElCard>
  </div>
</template>

