```typescript
import request from ''@/utils/http''

// 创建任务
export interface CreateTaskRequest {
  task_name: string
  task_type: 0 | 1 | 6
  subject_id: number
  expired_time: string
  description?: string
  student_ids: string[]
  student_expired_times?: Record<string, string>
  status: ''draft'' | ''published''
}

export interface CreateTaskResponse {
  task_id: string
  assignment_ids: string[]
}

export const createTask = (data: CreateTaskRequest) => {
  return request.post<CreateTaskResponse>(''/devices-study-room/shadow/v1/task-learning/create'', data)
}

// 查询任务列表
export interface ListTaskRequest {
  page: number
  page_size: number
  student_id?: string
  status?: ''draft'' | ''published'' | ''finished'' | ''expired''
  task_type?: 0 | 1 | 6
  subject_id?: number
  keyword?: string
}

export interface TaskListItem {
  assignment_id: string
  task_id: string
  task_name: string
  task_type: 0 | 1 | 6
  subject_id: number
  subject_name: string
  expired_time: string
  status: string
  student_count: number
  finished_student_count: number
  completion_rate: number
}

export interface ListTaskResponse {
  total: number
  list: TaskListItem[]
}

export const listTask = (data: ListTaskRequest) => {
  return request.post<ListTaskResponse>(''/devices-study-room/shadow/v1/task-learning/list'', data)
}

// 查询任务详情
export interface TaskDetailResponse {
  task_id: string
  task_name: string
  task_type: 0 | 1 | 6
  subject_id: number
  subject_name: string
  expired_time: string
  description: string
  created_at: string
  learning_companion_name: string
  statistics: {
    total_student_count: number
    finished_student_count: number
    unfinished_student_count: number
    average_accuracy: number
    average_duration: number
  }
  student_completions: Array<{
    student_id: string
    student_name: string
    done: boolean
    started: boolean
    finished_at?: string
    accuracy?: number
    duration?: number
    finished_item_count?: number
    correct_problem_count?: number
  }>
}

export const getTaskDetail = (taskId: string) => {
  return request.get<TaskDetailResponse>(`/devices-study-room/shadow/v1/task-learning/detail/${taskId}`)
}
```

#### 3.3.4 Hooks设计

**useTaskLearning Hook**（位置：`src/hooks/useTaskLearning.ts`）：

```typescript
import { ref, computed } from ''vue''
import { useTable } from ''@/hooks/core/useTable''
import { listTask, createTask, getTaskDetail, type ListTaskRequest, type CreateTaskRequest } from ''@/api/taskLearning''

export function useTaskLearning() {
  const { data, loading, fetchData, pagination } = useTable({
    core: {
      apiFn: (params: ListTaskRequest) => listTask(params),
    },
  })

  const createTaskLoading = ref(false)
  
  const handleCreateTask = async (formData: CreateTaskRequest) => {
    createTaskLoading.value = true
    try {
      const res = await createTask(formData)
      return res
    } finally {
      createTaskLoading.value = false
    }
  }

  const taskDetail = ref(null)
  const detailLoading = ref(false)
  
  const fetchTaskDetail = async (taskId: string) => {
    detailLoading.value = true
    try {
      const res = await getTaskDetail(taskId)
      taskDetail.value = res
      return res
    } finally {
      detailLoading.value = false
    }
  }

  return {
    // 列表相关
    taskList: computed(() => data.value?.list || []),
    total: computed(() => data.value?.total || 0),
    loading,
    fetchData,
    pagination,
    
    // 创建相关
    createTaskLoading,
    handleCreateTask,
    
    // 详情相关
    taskDetail,
    detailLoading,
    fetchTaskDetail,
  }
}
```

