│       ├── user.proto           # 用户相关 API
│       └── ...
├── internal/
│   ├── conf/                    # 配置定义
│   │   └── conf.proto           # 配置 Protobuf
│   ├── server/                  # Server 层（HTTP/gRPC）
│   │   ├── http.go              # HTTP 服务器
│   │   ├── grpc.go              # gRPC 服务器
│   │   └── server.go            # Server 注册
│   ├── service/                 # Service 层（业务接口实现）
│   │   ├── auth.go              # 认证服务
│   │   ├── user.go              # 用户服务
│   │   └── service.go           # Service 注册
│   ├── biz/                     # Biz 层（业务逻辑）
│   │   ├── auth.go              # 认证业务逻辑
│   │   ├── user.go              # 用户业务逻辑
│   │   └── biz.go               # Biz 注册
│   └── data/                    # Data 层（数据访问）
│       ├── data.go              # Data 初始化
│       ├── auth.go              # 认证数据访问
